/* Synthetic editorial text only for tests. Never loaded by a production provider. */
const news=require('../../../src/lib/news/core.cjs');
function editionFor(batch){
 const items=news.selectItems(batch.items,'Today',batch.asOf).slice(0,3);if(!items.length)throw Error('Test fixture needs same-day sources');
 const p=(label,ids,kind='analysis')=>({kind,evidenceIds:ids,text:{zh:'合成测试文稿：'+label+'。不代表真实新闻或分析。',en:'Synthetic test narrative: '+label+'. This is not a real news judgment.'}});
 return {schemaVersion:1,status:'published',date:news.shanghaiDay(batch.asOf),timeZone:'Asia/Shanghai',generatedAt:batch.asOf,sourceSnapshotAt:batch.asOf,provenance:{kind:'human',author:'Synthetic test fixture, not a real editorial author',evidenceReviewed:true,bilingualReviewed:true},sources:items.map(i=>({id:i.id,title:i.title,source:i.source,sourceUrl:i.sourceUrl,publishedAt:i.publishedAt,excerpt:i.summary})),executiveOpening:[p('opening one',[items[0].id]),p('opening two',items.map(i=>i.id))],stories:items.map((item,index)=>({id:'synthetic-story-'+index,title:{zh:'合成测试标题 '+index,en:'Synthetic test story '+index},newsIds:[item.id],confirmedFacts:[p('fact '+index,[item.id],'confirmed')],whyItMatters:[p('mechanism '+index,[item.id])],yearView:[p('long-range conditional view '+index,[item.id],'hypothesis')],opportunities:[p('opportunity condition '+index,[item.id],'hypothesis')],risks:[p('risk condition '+index,[item.id],'hypothesis')],...(index===0&&items.length>1?{crossAnalysis:[p('cross-source comparison',[item.id,items[1].id])]}:{})})),watchNext:[0,1,2].map(i=>p('observable check '+i,[items[0].id],'hypothesis')),keyword:{term:{zh:'合成测试概念',en:'Synthetic test concept'},explanation:p('concept explanation',[items[0].id])},framework:p('optional long-term framework',[items[0].id])};
}
module.exports={editionFor};
